class TestKyberConstants:
    """Verify all Kyber-1024 parameters match NIST FIPS 203 specifications."""

    @pytest.mark.parametrize(
        "name,expected",
        [
            ("KYBER_K", 4),
            ("KYBER_N", 256),
            ("KYBER_Q", 3329),
            ("KYBER_POLYBYTES", 384),
            ("KYBER_POLYVECBYTES", 4 * 384),
            ("KYBER_PUBLICKEYBYTES", 4 * 384 + 32),
            ("KYBER_SECRETKEYBYTES", 4 * 384 + 384 + 64),
            ("KYBER_CIPHERTEXTBYTES", 4 * 384 + 384),
            ("KYBER_SHAREDSECRETBYTES", 32),
        ],
    )
    def test_constant_values(self, header_content, name, expected):
        """Verify each constant matches the Kyber-1024 specification."""
        pattern = rf"#define\s+{name}\s+(\d+)"
        import re

        match = re.search(pattern, header_content)
        assert match, f"Constant {name} not found in header"
        assert int(match.group(1)) == expected, (
            f"{name} = {match.group(1)}, expected {expected}"
        )

    def test_derived_constant_consistency(self):
        """Verify derived constants are arithmetically consistent."""
        assert KYBER_POLYVECBYTES == KYBER_K * KYBER_POLYBYTES
        assert KYBER_PUBLICKEYBYTES == KYBER_POLYVECBYTES + 32
        assert KYBER_SECRETKEYBYTES == (
            KYBER_POLYVECBYTES + KYBER_POLYBYTES + 2 * 32
        )
        assert KYBER_CIPHERTEXTBYTES == KYBER_POLYVECBYTES + KYBER_POLYBYTES

    def test_kyber_security_level(self):
        """Kyber-1024 must have k=4, n=256, q=3329 per FIPS 203."""
        assert KYBER_K == 4, "Kyber-1024 requires K=4"
        assert KYBER_N == 256, "Kyber-1024 requires N=256"
        assert KYBER_Q == 3329, "Kyber-1024 requires Q=3329"

    def test_constant_size_bounds(self):
        """All sizes must be positive and within reasonable bounds."""
        sizes = [
            KYBER_POLYBYTES,
            KYBER_POLYVECBYTES,
            KYBER_PUBLICKEYBYTES,
            KYBER_SECRETKEYBYTES,
            KYBER_CIPHERTEXTBYTES,
            KYBER_SHAREDSECRETBYTES,
        ]
        assert all(s > 0 for s in sizes)
        assert all(s < 10000 for s in sizes), "Sizes exceed expected bounds"


