# Test Class 3: secure_malloc Contract Validation
# =============================================================================
class TestSecureMalloc:
    """Validate secure_malloc behavior through the compiled shim."""

    @pytest.fixture(autouse=True)
    def setup_malloc(self, compiled_library):
        self.malloc = compiled_library.test_secure_malloc
        self.malloc.restype = ctypes.c_void_p
        self.malloc.argtypes = [ctypes.c_size_t]
        self.free = compiled_library.test_free
        self.free.argtypes = [ctypes.c_void_p]

    @given(st.integers(min_value=1, max_value=1024 * 1024))
    @settings(max_examples=50, deadline=None)
    def test_malloc_returns_non_null(self, size):
        """secure_malloc must return a valid pointer for positive sizes."""
        ptr = self.malloc(size)
        assert ptr is not None, f"secure_malloc({size}) returned NULL"
        self.free(ptr)

    @given(st.integers(min_value=1, max_value=4096))
    @settings(max_examples=20, deadline=None)
    def test_malloc_memory_is_zeroed(self, size):
        """Memory returned by secure_malloc must be zero-initialized."""
        ptr = self.malloc(size)
        assert ptr is not None
        buffer = ctypes.string_at(ptr, size)
        assert all(b == 0 for b in buffer), (
            f"Memory not zeroed at offset {next(i for i, b in enumerate(buffer) if b != 0)}"
        )
        self.free(ptr)

    def test_malloc_zero_size(self):
        """Zero-size allocation should return NULL or a valid pointer (implementation-defined)."""
        ptr = self.malloc(0)
        # Both behaviors are acceptable per C standard
        if ptr is not None:
            self.free(ptr)

    def test_malloc_huge_size(self):
        """Huge allocation should fail gracefully (return NULL)."""
        ptr = self.malloc(2**63 - 1)
        assert ptr is None, "Huge allocation should fail"

    @given(st.integers(min_value=1, max_value=100))
    @settings(max_examples=10, deadline=None)
    def test_malloc_multiple_allocations(self, count):
        """Multiple allocations should not interfere."""
        pointers = []
        for _ in range(count):
            ptr = self.malloc(64)
            assert ptr is not None
            pointers.append(ptr)
        for ptr in pointers:
            self.free(ptr)

    def test_malloc_alignment(self):
        """Memory should be suitably aligned for any data type (max_align_t)."""
        ptr = self.malloc(16)
        assert ptr is not None
        address = int(ptr)
        assert address % 16 == 0, f"Pointer {hex(address)} not 16-byte aligned"
        self.free(ptr)


