# Test Class 9: Edge Cases
# =============================================================================
class TestEdgeCases:
    """Test edge cases in constant definitions."""

    def test_kyber_q_is_prime(self):
        """Kyber modulus Q must be prime."""
        assert KYBER_Q == 3329
        # Verify primality
        for i in range(2, int(KYBER_Q**0.5) + 1):
            assert KYBER_Q % i != 0, f"{KYBER_Q} divisible by {i}"

    def test_kyber_n_power_of_two(self):
        """Kyber N must be a power of 2."""
        assert KYBER_N == 256
        assert (KYBER_N & (KYBER_N - 1)) == 0

    def test_kyber_k_valid_range(self):
        """Kyber K must be 2, 3, or 4 for security levels 512, 768, 1024."""
        assert KYBER_K in [2, 3, 4]

    def test_polybytes_correct(self):
        """Polynomial bytes = N * log2(Q) / 8 = 256 * 12 / 8 = 384."""
        assert KYBER_POLYBYTES == 384
        assert KYBER_POLYBYTES == (KYBER_N * 12) // 8

    def test_constant_overflow_safety(self):
        """All constants must fit in 32-bit integers."""
        constants = [
            KYBER_K,
            KYBER_N,
            KYBER_Q,
            KYBER_POLYBYTES,
            KYBER_POLYVECBYTES,
            KYBER_PUBLICKEYBYTES,
            KYBER_SECRETKEYBYTES,
            KYBER_CIPHERTEXTBYTES,
            KYBER_SHAREDSECRETBYTES,
        ]
        assert all(c < 2**31 for c in constants)


